#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using UniversalModuleFramework.Core;
using UniversalModuleFramework.Repositories;
using UniversalModuleFramework.UnitOfWork;
using RefModels = UniversalWorkflowFramework.Reference.Models;

namespace RelationshipManagement.Orchestration
{
    /// <summary>模块间 DependsOn 关系编排，从 ModuleCatalog 下沉到引用语义层。</summary>
    public class ModuleDependencyOrchestrator
    {
        private readonly IModuleUnitOfWork _uow;

        public ModuleDependencyOrchestrator(IModuleUnitOfWork uow)
        {
            _uow = uow ?? throw new ArgumentNullException(nameof(uow));
        }

        public async Task<bool> AddDependencyAsync(string sourceId, string targetId, string? versionConstraint = null, CancellationToken ct = default)
        {
            var rel = new ModuleRelationshipRecord { Id = Guid.NewGuid().ToString("N"), SourceId = sourceId, TargetId = targetId, Type = RefModels.ReferenceType.Dependency, VersionConstraint = versionConstraint };
            var success = await _uow.Relationships.AddAsync(rel, ct);
            if (success) await _uow.SaveChangesAsync(ct);
            return success;
        }

        public async Task<IReadOnlyList<IModule>> GetDependenciesAsync(string moduleId, CancellationToken ct = default)
        {
            var rels = await _uow.Relationships.GetOutgoingAsync(moduleId, RefModels.ReferenceType.Dependency, ct);
            if (rels.Count == 0) return Array.Empty<IModule>();
            var modules = await Task.WhenAll(rels.Select(r => r.TargetId).Distinct().Select(id => _uow.Modules.GetByIdAsync(id, ct)));
            return modules.Where(m => m != null).Cast<IModule>().ToList();
        }

        public async Task<IReadOnlyList<IModule>> GetDependentsAsync(string moduleId, CancellationToken ct = default)
        {
            var rels = await _uow.Relationships.GetIncomingAsync(moduleId, RefModels.ReferenceType.Dependency, ct);
            if (rels.Count == 0) return Array.Empty<IModule>();
            var modules = await Task.WhenAll(rels.Select(r => r.SourceId).Distinct().Select(id => _uow.Modules.GetByIdAsync(id, ct)));
            return modules.Where(m => m != null).Cast<IModule>().ToList();
        }
    }
}
